import { FC, HTMLAttributes } from 'react';
import { useTranslation } from 'react-i18next';
import { Link } from 'react-router-dom';

import { ClockCircleOutlined } from '@ant-design/icons';

import { Flex, Input, Typography } from 'antd';
import cn from 'classnames';

// import chickImage from 'assets/images/chick.webp';
import ChannelsIcon from 'assets/images/icons/dashboard/cahnnels.svg?react';
// import CollectionsIcon from 'assets/images/icons/dashboard/collections.svg?react';
import SettingsIcon from 'assets/images/menu/settings.svg?react';
import StatsIcon from 'assets/images/menu/stats.svg?react';
import { ReportSummaryItem, useStatisticsChartListQuery } from 'entities/Report';
import { EFilters } from 'features/Filters';
import { Planner } from 'features/Planner';
import { useAppConfigRetrieveQuery } from 'shared/api';
import { EMainRoutes, EYmPageScreen } from 'shared/typings';
import { Content, DashboardLink, LastProfit } from 'shared/ui';
import { formatDate, formatNumber, isAndroid, isIOS, sendYmEvent } from 'shared/utils';

import styles from './Dashboard.module.scss';

interface IDashboardProps extends HTMLAttributes<HTMLDivElement> {}

export const Dashboard: FC<IDashboardProps> = ({ className, ...props }) => {
	const { t } = useTranslation();
	const { data: appConfig } = useAppConfigRetrieveQuery();

	const currentDateAfter = new Date();
	const currentDateBefore = new Date();
	const prevDateAfter = new Date();
	const prevDateBefore = new Date();
	currentDateAfter.setHours(0, 0, 0, 0);
	currentDateBefore.setHours(0, 0, 0, 0);
	prevDateAfter.setHours(0, 0, 0, 0);
	prevDateBefore.setHours(0, 0, 0, 0);

	currentDateAfter.setDate(currentDateAfter.getDate() - 7);
	prevDateAfter.setDate(prevDateAfter.getDate() - 14);
	prevDateBefore.setDate(prevDateBefore.getDate() - 7);

	const { data: currentData, isFetching: currentIsFetching } = useStatisticsChartListQuery({
		[EFilters.AGGREGATE_BY]: 'day',
		[EFilters.DATE_AFTER]: `${formatDate(currentDateAfter, 'iso')}`,
		[EFilters.DATE_BEFORE]: `${formatDate(currentDateBefore, 'iso')}`,
	});

	const { data: prevData, isFetching: prevIsFetching } = useStatisticsChartListQuery({
		[EFilters.AGGREGATE_BY]: 'day',
		[EFilters.DATE_AFTER]: `${formatDate(prevDateAfter, 'iso')}`,
		[EFilters.DATE_BEFORE]: `${formatDate(prevDateBefore, 'iso')}`,
	});

	const currentClicks = currentData?.reduce((acc, item) => acc + Number(item.clicks_count), 0) || 0;
	const prevClicks = prevData?.reduce((acc, item) => acc + Number(item.clicks_count), 0) || 0;
	const currentConversions = currentData?.reduce((acc, item) => acc + Number(item.actions_count), 0) || 0;
	const prevConversions = prevData?.reduce((acc, item) => acc + Number(item.actions_count), 0) || 0;

	const currentClicksArrow = currentClicks > prevClicks ? 'up' : currentClicks < prevClicks ? 'down' : 'equal';
	const currentConversionsArrow =
		currentConversions > prevConversions ? 'up' : currentConversions < prevConversions ? 'down' : 'equal';

	return (
		<Flex {...props} vertical className={cn(className, styles.dashboard)}>
			<Content bordered={false}>
				<Flex vertical gap={8}>
					{isIOS || isAndroid ? (
						<Input
							type="time"
							defaultValue="10:22"
							placeholder={t('Выберите время')}
							className={styles.postForm__fx}
							size="large"
							value={'10:22'}
							style={{ width: '118px' }}
							suffix={<ClockCircleOutlined className={styles.clock} />}
						/>
					) : (
						'sds'
					)}
					{(appConfig?.user?.tg_username || appConfig?.user?.tg_first_name || appConfig?.user?.tg_last_name) && (
						<DashboardLink to={EMainRoutes.PROFILE}>
							<Flex align="center" gap={12}>
								<img
									style={{ borderRadius: '50%' }}
									src={appConfig?.user?.tg_photo_url}
									width={40}
									height={40}
									alt=""
								/>
								<Flex vertical>
									<Typography.Text style={{ fontSize: 16 }}>
										{appConfig?.user?.tg_first_name || appConfig?.user?.tg_last_name
											? `${appConfig?.user?.tg_first_name} ${appConfig?.user?.tg_last_name}`
											: appConfig?.user?.tg_username}
									</Typography.Text>
									<Typography.Text type="secondary" style={{ fontSize: 12 }}>
										{t('Перейти в профиль')}
									</Typography.Text>
								</Flex>
							</Flex>
						</DashboardLink>
					)}

					<Flex gap={8}>
						<DashboardLink
							to={EMainRoutes.REPORTS}
							onClick={() => sendYmEvent('click_statistics', { page_screen: EYmPageScreen.MAIN_SCREEN })}
							title={t('Статистика')}
							icon={<StatsIcon />}
							type="vertical"
						/>
						<DashboardLink
							to={EMainRoutes.SETTINGS}
							onClick={() => sendYmEvent('click_settings', { page_screen: EYmPageScreen.MAIN_SCREEN })}
							title={t('Настройки')}
							icon={<SettingsIcon />}
							type="vertical"
						/>
					</Flex>

					{/*<ConfigProvider*/}
					{/*	theme={{*/}
					{/*		components: {*/}
					{/*			Button: {*/}
					{/*				defaultBg: '#ffffff',*/}
					{/*				defaultHoverBg: '#ffffff',*/}
					{/*				defaultActiveBg: '#ffffff',*/}
					{/*				defaultBorderColor: '#E0E0E1',*/}
					{/*				defaultHoverBorderColor: '#E0E0E1',*/}
					{/*				defaultActiveBorderColor: '#E0E0E1',*/}
					{/*				defaultColor: '#1E1E1F',*/}
					{/*			},*/}
					{/*		},*/}
					{/*	}}>*/}
					{/*	<Flex gap={8} align="center" justify="space-between" className={styles.tasks}>*/}
					{/*		<Flex gap={8} align="center">*/}
					{/*			<img src={chickImage} alt="" width={32} height={32} />*/}
					{/*			<Typography.Text strong className={styles.tasksTitle}>*/}
					{/*				{t('Награды за первые шаги')}*/}
					{/*			</Typography.Text>*/}
					{/*		</Flex>*/}
					{/*		<ButtonStyleLink to={`/${EMainRoutes.TASKS}`}>{t('Начать')}</ButtonStyleLink>*/}
					{/*	</Flex>*/}
					{/*</ConfigProvider>*/}

					<DashboardLink
						to={EMainRoutes.CHANNELS}
						onClick={() => sendYmEvent('click_my_channels', { page_screen: EYmPageScreen.MAIN_SCREEN })}
						title={t('Каналы и группы')}
						icon={<ChannelsIcon />}
					/>
					{/*<DashboardLink to={EMainRoutes.COLLECTIONS} title={t('Коллекции')} icon={<CollectionsIcon />} />*/}

					<LastProfit pageScreen={EYmPageScreen.MAIN_SCREEN} />

					<Flex gap={8}>
						<ReportSummaryItem
							isDashboard
							arrow={currentClicksArrow}
							summ={formatNumber(currentClicks) || ''}
							description={t('За 7 дней, кликов')}
							isFetching={currentIsFetching || prevIsFetching}
						/>
						<ReportSummaryItem
							isDashboard
							arrow={currentConversionsArrow}
							summ={formatNumber(currentConversions) || ''}
							description={t('За 7 дней, конверсий')}
							isFetching={currentIsFetching || prevIsFetching}
						/>
					</Flex>
				</Flex>
			</Content>

			<Content filled className={styles.planner}>
				<Flex vertical gap={8}>
					<Flex align="center" justify="space-between" gap={8}>
						<Typography.Title level={5} style={{ margin: 0 }}>
							{t('Ваши посты')}
						</Typography.Title>
						<Link
							to={`/${EMainRoutes.PLANNER}`}
							onClick={() => sendYmEvent('click_scheduler', { page_screen: EYmPageScreen.MAIN_SCREEN })}>
							{t('Планировщик')}
						</Link>
					</Flex>

					<Planner isInner />
				</Flex>
			</Content>
		</Flex>
	);
};

export default Dashboard;
